      await fs.writeFile(path.join(worktreeDir, 'test.yaml'), 'test: unauthorized');
      execSync('git add -A', { cwd: worktreeDir, stdio: 'pipe' });

      // Attempt commit without KSPEC_SHADOW_COMMIT - should fail
      try {
