      const readme = await fs.readFile(path.join(testDir, 'README.md'), 'utf-8');
      expect(readme).toBe('# Test');
      const src = await fs.readFile(path.join(testDir, 'src.ts'), 'utf-8');
      expect(src).toBe('export const x = 1;');

